// round 2 additions live in registry-more.js; keep every category together, in dial order
const order = Object.fromEntries(CATEGORIES.map((c, i) => [c.id, i]));
export const ANIMS = [...BASE, ...MORE].sort((a, b) => order[a.cat] - order[b.cat]);
export const catById = Object.fromEntries(CATEGORIES.map(c => [c.id, c]));
export const animById = Object.fromEntries(ANIMS.map(a => [a.id, a]));
export const srcOf = a => `anims/${a.cat}/${a.id}.js`;
